H_SURFACE = "## 7. Surface construction\nEach day becomes a constant-maturity grid. *Observed* = an expiry within about a day of the tenor and two adjacent real quotes (< 0.02 apart in k) bracket the node; *interpolated_k* = same expiry but sparse strikes; *interpolated_T* = total-variance interpolation between two real expiries; *missing* = outside the real quotes. Nothing is extrapolated."

SURFACE_PLOTS = r"""from mpl_toolkits.mplot3d import Axes3D  # noqa: F401
dts = panel["dates"].astype("datetime64[D]"); st, iv = panel["status"], panel["iv"]
nT, nK = len(TENOR_DAYS), len(K_NODES)
fig, axs = plt.subplots(1, 4, figsize=(19, 3.6))
for a, (c, name) in zip(axs, [(3, "observed"), (2, "interpolated_k"), (1, "interpolated_T"), (0, "missing")]):
    im = a.imshow((st == c).mean(axis=0), vmin=0, vmax=1, cmap="viridis", aspect="auto")
    a.set_xticks(range(nK)); a.set_xticklabels([f"{k:+.2f}" for k in K_NODES], rotation=60, fontsize=7)
    a.set_yticks(range(nT)); a.set_yticklabels(TENOR_DAYS); a.set_title(name); a.set_xlabel("log-moneyness k"); a.set_ylabel("tenor (days)")
fig.colorbar(im, ax=axs, fraction=0.012); fig.suptitle(f"Share of days each cell has each status  [{DATA_LABEL}]"); savefig("status_share_heatmaps"); plt.show()

good = np.flatnonzero((st > 0).mean(axis=(1, 2)) > 0.6)
pick = [good[len(good) // 5], good[len(good) // 2], good[4 * len(good) // 5]] if len(good) >= 5 else list(good[:3])
fig, axs = plt.subplots(1, len(pick), figsize=(6 * len(pick), 4), squeeze=False)
for a, i in zip(axs[0], pick):
    for j, tau in enumerate(TENOR_DAYS):
        ok = st[i, j] > 0; col = f"C{j}"
        a.plot(np.array(K_NODES)[ok], iv[i, j][ok] * 100, "-", color=col, alpha=0.5)
        obs = st[i, j] == 3
        a.plot(np.array(K_NODES)[obs], iv[i, j][obs] * 100, "o", color=col, label=f"{tau}d")
        a.plot(np.array(K_NODES)[ok & ~obs], iv[i, j][ok & ~obs] * 100, "o", mfc="none", color=col)
    a.set_title(str(dts[i])); a.set_xlabel("log-moneyness k"); a.set_ylabel("IV (vol pts)"); a.grid(alpha=0.3)
axs[0][0].legend(title="filled = observed\nhollow = interpolated", fontsize=7)
fig.suptitle(f"Maturity/skew slices on three dates  [{DATA_LABEL}]"); savefig("surface_slices"); plt.show()

i = pick[1]
fig = plt.figure(figsize=(7, 5)); ax = fig.add_subplot(111, projection="3d")
KK, TT = np.meshgrid(K_NODES, TENOR_DAYS)
Z = np.where(st[i] > 0, iv[i] * 100, np.nan)
ax.plot_surface(KK, TT, np.ma.masked_invalid(Z), cmap="viridis", alpha=0.85)
ax.set_xlabel("k"); ax.set_ylabel("tenor (d)"); ax.set_zlabel("IV (pts)"); ax.set_title(f"{dts[i]}  [{DATA_LABEL}]"); savefig("surface_3d"); plt.show()

j30 = TENOR_DAYS.index(30) if 30 in TENOR_DAYS else 0; k0 = K_NODES.index(0.0) if 0.0 in K_NODES else 0
fig, axs = plt.subplots(2, 1, figsize=(12, 5), sharex=True)
axs[0].plot(dts, np.where(st[:, j30, k0] > 0, iv[:, j30, k0] * 100, np.nan), lw=0.8); axs[0].set_ylabel(f"ATM IV, {TENOR_DAYS[j30]}d (pts)")
axs[1].plot(dts, (st > 0).mean(axis=(1, 2)), lw=0.8, label="non-missing"); axs[1].plot(dts, (st == 3).mean(axis=(1, 2)), lw=0.8, label="observed")
axs[1].set_ylabel("share of cells"); axs[1].legend(); fig.suptitle(f"ATM level and surface coverage over time  [{DATA_LABEL}]"); savefig("atm_and_coverage"); plt.show()
print("static-arbitrage diagnostics (flags only; NOT a proof of arbitrage-freedom):"); display(pd.Series(built["arbitrage_diagnostics"]).to_frame("value"))
"""

H_FEATURES = "## 8. Feature engineering and leakage audit\n**Target:** `y(t+h, cell) - s(t, cell)` for `h` = `HORIZON` trading days. **Features at origin t (only rows <= t):** the causally forward-filled surface `s(t)`, its changes over 1 and 5 rows, realised vol of the underlying (5/20 rows), and the share of cells with a real value. The GRU sees the last `SEQ_LEN` days of [surface, availability mask, realised vols]. **Fitted on training rows only:** per-cell fill means, feature scalers, PCA, ridge penalty selection (validation year), early stopping (validation year)."

FEATURES = r"""p = prepare(panel, cfg.features)
folds = make_folds(p, cfg.split)
rows = []
for f in folds:
    assert_no_overlap(p, f)
    od = p.dates[p.origins].astype("datetime64[D]")
    rows.append({"test_year": f.test_year, "val_year": f.val_year, "train_from": str(od[f.train].min()), "train_to": str(od[f.train].max()),
                 "n_train": len(f.train), "n_val": len(f.val), "n_test": len(f.test)})
fold_table = pd.DataFrame(rows); display(fold_table)
print(f"origins: {len(p.origins)} | cells per surface: {p.n_cells} | horizon: {cfg.features.horizon} row(s)")
print("chronology asserts passed for every fold (train labels < validation origins < validation labels < test origins)")
LEAK = feature_invariance_check(p, cfg)
print("leakage audit (features at origins <= t must not change when every later row is scrambled):", LEAK)
assert LEAK["passed"], "LEAKAGE DETECTED"
FEATURE_DEFS = {
    "target": "y(t+h, cell) - s(t, cell); h=%d trading day(s); evaluated on cells OBSERVED at t+h with a real value at t" % cfg.features.horizon,
    "tabular_blocks": ["s_t (filled surface, %d cells)" % p.n_cells] + ["s_t - s_(t-%d)" % l for l in cfg.features.lags] +
                      ["realised_vol_%d" % w for w in cfg.features.rv_windows] + ["share_of_cells_with_real_value"],
    "sequence": "last %d rows of [filled surface, availability mask, realised vols]" % cfg.features.seq_len,
    "fit_on_training_rows_only": ["per-cell fill means", "feature scalers", "PCA basis", "ridge penalty (validation year)", "early stopping (validation year)"],
    "regime_cutoffs": "realised-vol terciles from training origins of each fold",
}
print(json.dumps(FEATURE_DEFS, indent=1))
"""

