HIST = pd.DataFrame(hist); display(HIST.groupby(HIST.run.str.extract(r"_(mlp|gru)_")[0]).agg(runs=("run", "count"), epochs_mean=("epochs_run", "mean"), best_epoch_mean=("best_epoch", "mean"), seconds_total=("seconds", "sum"), peak_gpu_mb=("peak_gpu_mb", "max")).round(2))
fig, axs = plt.subplots(1, len(MODELS), figsize=(6 * len(MODELS), 3.6), squeeze=False)
for a, kind in zip(axs[0], MODELS):
    for fp in sorted((OUT_DIR / "histories").glob(f"*_{kind}_seed0.json")):
        h = json.loads(fp.read_text()); a.plot(h["history"]["val_loss"], lw=1, label=fp.stem.split("_")[0]); a.plot(h["history"]["train_loss"], lw=0.6, ls=":", color=a.lines[-1].get_color())
    a.set_title(f"{kind.upper()}: validation (solid) / train (dotted) loss, seed 0"); a.set_xlabel("epoch"); a.set_ylabel("masked MSE (standardised)"); a.legend(fontsize=6, ncol=2)
savefig("training_curves"); plt.show()
